<script setup lang="ts">
import { computed,reactive,ref,watch,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { ArrowLeftIcon,ChevronDownIcon,ArrowPathIcon } from '@heroicons/vue/24/outline'
import GitHubPanel from '../components/GitHubPanel.vue'
import NotesPanel from '../components/NotesPanel.vue'
import AssignmentPanel from '../components/AssignmentPanel.vue'
import { makeNoteDraft,noteDirty,activityLabel } from '../composables/collaboration'
import { bootstrap,api,notify,ApiError } from '../composables/api'
import { useInvestigation,queryString,date,zone } from '../composables/investigation'
import type { DetailResult,Frame } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<DetailResult>(()=>'/issues/'+route.params.issue+'?'+queryString(route.query,['returnTo','tab']))
const noteDraft=reactive(makeNoteDraft())
function leaveNotes(){return !noteDirty(noteDraft)||window.confirm('Discard your unsaved note draft before leaving this error?')}
onBeforeRouteLeave(leaveNotes)
onBeforeRouteUpdate((to,from)=>to.params.issue===from.params.issue||leaveNotes())
const noteUnload=(e:BeforeUnloadEvent)=>{if(noteDirty(noteDraft)){e.preventDefault();e.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',noteUnload));onUnmounted(()=>window.removeEventListener('beforeunload',noteUnload))
const tab=computed(()=>typeof route.query.tab==='string'?route.query.tab:'stack'),vendor=ref(false),snoozing=ref(false),duration=ref('24'),custom=ref(''),acting=ref(false),conflict=ref('')
const selected=computed(()=>data.value?.selected), payload=computed(()=>selected.value?.evidence)
const back=computed(()=>typeof route.query.returnTo==='string'&&/^\/(errors|overview)(\?|$)/.test(route.query.returnTo)?route.query.returnTo:'/errors')
const frames=computed<Frame[]>(()=>payload.value?[{file:payload.value.exception.file,line:payload.value.exception.line,class:payload.value.exception.class,source_url:selected.value?.source_url},...payload.value.exception.trace]:[])
const isVendor=(f:Frame)=>f.file.startsWith('vendor/')||f.file.includes('/vendor/')
const visibleFrames=computed(()=>vendor.value?frames.value:frames.value.filter(f=>!isVendor(f)))
watch(()=>route.params.issue,()=>{conflict.value='';snoozing.value=false;vendor.value=false;Object.assign(noteDraft,makeNoteDraft())})
watch(()=>selected.value?.id,(id)=>{if(id&&!route.query.occurrence)router.replace({query:{...route.query,occurrence:id}})})
function choose(id:string){router.replace({query:{...route.query,occurrence:id}})}
function page(n:number){router.replace({query:{...route.query,page:String(n)}})}
let attempt:{intent:string;key:string;until?:string}|null=null
async function act(action:string){if(!data.value||acting.value)return;acting.value=true;conflict.value=''
 try {let until:string|undefined;if(action==='snooze'){if(duration.value==='custom'){if(!/(Z|[+-]\d{2}:\d{2})$/i.test(custom.value)||Number.isNaN(Date.parse(custom.value)))throw new Error('Enter a future ISO date and time with a UTC offset.');until=new Date(custom.value).toISOString()}else until=new Date(Date.now()+Number(duration.value)*3600000).toISOString()}
 const intent=JSON.stringify([data.value.issue.id,data.value.issue.state_version,action,duration.value,custom.value]);if(attempt?.intent!==intent)attempt={intent,key:crypto.randomUUID(),until};until=attempt.until
 await api('/issues/'+data.value.issue.id+'/actions','POST',{client_key:attempt.key,version:data.value.issue.state_version,action,...(until?{until}:{})});attempt=null;snoozing.value=false;notify('Error state updated.');await reload()
 }catch(e){if(e instanceof ApiError && e.status<500)attempt=null;if(e instanceof ApiError && e.status===409)conflict.value=e.message;else notify(e instanceof Error?e.message:'The action could not be completed.',true)}finally{acting.value=false}
}
</script>
<template><RouterLink :to="back" class="back-link"><ArrowLeftIcon/>Back to filtered errors</RouterLink><p v-if="loading" role="status" class="loading-message">Loading occurrence…</p><div v-if="error" class="notice danger" role="alert">{{ error }}<button class="button" @click="reload">Try again</button></div><template v-if="data"><div class="error-heading"><div><div class="issue-identifiers"><span class="status-badge" :class="'status-'+data.issue.status">{{data.issue.status}}</span><span v-if="data.issue.regressions" class="badge">Regression</span><span v-if="data.issue.is_test" class="badge">Test event</span><span v-if="data.issue.recovered_only" class="badge" title="Only historical or recovered occurrences so far">Historical</span><span>{{ selected?.origin??'Unknown origin' }} · {{data.issue.environment}}</span></div><h1 :title="data.issue.message">{{data.issue.message || data.issue.class}}</h1><p>{{data.issue.class}} · <span class="code">{{data.issue.file}}:{{data.issue.line}}</span></p></div><div v-if="bootstrap?.capabilities.operate" class="lifecycle-actions"><button v-if="data.issue.status==='unresolved'" class="button primary" :disabled="acting" @click="act('resolve')">Resolve</button><button v-if="['resolved','ignored'].includes(data.issue.status)" class="button primary" :disabled="acting" @click="act('reopen')">Reopen</button><button v-if="data.issue.status==='unresolved'" class="button" :disabled="acting" :aria-expanded="snoozing" @click="snoozing=!snoozing">Snooze</button><button v-if="data.issue.status==='snoozed'" class="button primary" :disabled="acting" @click="act('unsnooze')">Unsnooze</button><button v-if="data.issue.status!=='ignored'" class="button" :disabled="acting" @click="act('ignore')">Ignore</button><button class="button icon-button" aria-label="Refresh error" :disabled="acting" @click="reload"><ArrowPathIcon/></button></div></div><div v-if="conflict" class="notice warning" role="alert">{{conflict}}<button class="button" @click="conflict='';reload()">Reload current error</button></div><form v-if="snoozing" class="snooze-form" @submit.prevent="act('snooze')"><label class="field">Snooze duration<select v-model="duration"><option value="1">1 hour</option><option value="24">24 hours</option><option value="168">7 days</option><option value="custom">Future date and time</option></select></label><label v-if="duration==='custom'" class="field">Future time with UTC offset<input v-model="custom" placeholder="2026-11-12T12:00:00+05:30" required><small>Displayed timezone: {{zone()}}. An explicit offset avoids ambiguous daylight-saving times.</small></label><p class="help">Occurrences keep counting. Automatic occurrence alerts are suppressed until expiry; an in-flight external send cannot be recalled.</p><button class="button primary" :disabled="acting">Confirm snooze</button><button class="button" type="button" @click="snoozing=false">Cancel</button></form><div v-if="data.issue.status==='snoozed'" class="notice neutral">Snoozed until {{date(data.issue.snoozed_until)}} · {{zone()}}</div><nav class="detail-tabs" aria-label="Investigation sections"><RouterLink v-for="(name,key) in {stack:'Stack trace',context:'Context & timeline',insights:'Insights',activity:'Notes & activity',links:'Linked issues'}" :key="key" :class="{selected:tab===key}" :aria-current-value="tab===key?'page':'false'" :to="{query:{...route.query,tab:key}}">{{name}}</RouterLink></nav><div class="investigation-grid" :class="{'has-assignment':bootstrap?.features.assignments}"><AssignmentPanel v-if="bootstrap?.features.assignments" :issue="data.issue" @changed="reload"/><section class="panel occurrence-panel"><div class="selected-heading"><span>Selected occurrence</span><h2>{{selected?date(selected.occurred_at):'No occurrence available'}} <small>{{zone()}}</small></h2><span v-if="selected?.mode!=='live'" class="badge">{{selected?.mode==='historical_import'?'Historical import':selected?.mode}}</span><p v-if="selected?.mode==='historical_import'" class="help">Imported from Telescope history. Original reportability and deployment release were not verified. No retrospective alert was generated.</p></div><div v-if="!payload && ['stack','context'].includes(tab)" class="evidence-unavailable"><h3>{{selected?.evidence_state==='expired'?'Retained evidence expired':selected?.evidence_state==='decryption_failed'?'Retained evidence could not be decrypted':'No retained snapshot'}}</h3><p>The error summary and occurrence identity remain available. Choose another retained occurrence from the history.</p><RouterLink v-if="bootstrap?.capabilities.manage" to="/settings/health" class="text-link">Review system health</RouterLink></div><template v-else><p v-if="payload" class="exception-message">{{payload.exception.message}}</p><template v-if="tab==='stack' && payload"><div v-if="!frames.length" class="notice neutral">Stack trace {{payload.coverage.trace??'unavailable'}}.</div><div class="stack-frames"><div v-for="(frame,index) in visibleFrames" :key="index" class="stack-frame" :class="{application:!isVendor(frame)}"><span class="frame-number">{{index}}</span><div><strong>{{frame.class??''}}{{frame.function?'::'+frame.function+'()':''}}</strong><div class="code"><a v-if="frame.source_url" :href="frame.source_url" target="_blank" rel="noopener noreferrer">{{frame.file}}:{{frame.line}}</a><span v-else>{{frame.file}}:{{frame.line}}</span></div></div></div><button v-if="frames.some(isVendor)" class="vendor-toggle" :aria-expanded="vendor" @click="vendor=!vendor"><ChevronDownIcon/>{{vendor?'Hide':'Show'}} {{frames.filter(isVendor).length}} vendor frames</button></div><p class="help">Trace coverage: {{payload.coverage.trace}}. Code previews are not read from the currently deployed filesystem. Source links require a captured immutable release and code-host mapping.</p></template><template v-else-if="tab==='context' && payload"><h3>Execution context</h3><dl class="context-list"><div v-for="(value,key) in payload.execution" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl><p v-if="!Object.keys(payload.execution).length">Execution context {{payload.coverage.execution}}.</p><h3>Timeline</h3><ol class="timeline-list"><li v-for="(event,index) in payload.timeline" :key="index"><strong>{{event.type}}</strong><span v-for="(value,key) in event" :key="key">{{key!=='type'?value:''}} </span></li></ol><p v-if="!payload.timeline.length">No retained timeline events. Logs: {{payload.coverage.logs}}; execution: {{payload.coverage.execution}}.</p><h3>Tags</h3><dl class="context-list"><div v-for="(value,key) in payload.tags" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl><p class="help">Request bodies, cookies, headers, SQL bindings and arbitrary log context are excluded. Coverage: {{Object.entries(payload.coverage).map(([k,v])=>k+': '+v).join(' · ')}}</p></template><template v-else-if="tab==='insights'"><h3>Retained evidence insights</h3><p>{{data.insights.retained_count}} snapshots · {{date(data.insights.from)}} to {{date(data.insights.to)}}</p><div v-for="name in ['origin','route','release','tags'] as const" :key="name" class="insight-block"><h3>{{name}}</h3><ul><li v-for="entry in data.insights.breakdowns[name]" :key="entry.value">{{entry.value}} <strong>{{entry.count}}</strong></li></ul><p v-if="!data.insights.breakdowns[name].length">No retained {{name}} snapshot was available.</p></div><p>Affected users: {{data.insights.breakdowns.users?data.insights.breakdowns.users+' pseudonymous identifiers':'Unavailable or excluded by policy'}}</p><p class="help">{{data.insights.coverage}}</p></template><template v-else-if="tab==='activity'"><NotesPanel v-if="bootstrap?.features.collaboration" :issue="data.issue.id" :draft="noteDraft" @changed="reload"/><p v-else class="notice neutral">Publish and run the collaboration migration to enable notes.</p><h3 class="activity-title">Activity</h3><p class="help">Showing the latest 100 activity entries. Note text is not duplicated here.</p><ul class="activity-list"><li v-for="a in data.activity" :key="a.id"><div><strong>{{activityLabel(a.type)}}</strong><p class="help">{{a.actor}}<template v-if="a.metadata.previous||a.metadata.status"> · {{a.metadata.previous}} {{a.metadata.status?'→ '+a.metadata.status:''}}</template></p></div><p v-if="['error.assigned','error.unassigned'].includes(a.type)" class="help">Assignee: {{a.metadata.assignee_label??'Unassigned'}}<span v-if="a.metadata.previous_assignee_label"> (previously {{a.metadata.previous_assignee_label}})</span></p><time>{{date(a.at)}}</time></li></ul></template><template v-else><GitHubPanel :issue="data.issue.id"/></template></template></section><aside class="detail-rail"><section class="panel"><h2>Error summary</h2><dl class="summary-list"><div><dt>Lifetime occurrences</dt><dd>{{data.issue.lifetime_count}}</dd></div><div><dt>{{data.window.range}}</dt><dd>{{data.issue.range_count}}</dd></div><div><dt>First seen</dt><dd>{{date(data.issue.first_seen_at)}}</dd></div><div><dt>Last seen</dt><dd>{{date(data.issue.last_seen_at)}}</dd></div></dl></section><section class="panel occurrence-picker"><div class="section-heading"><h2>Occurrences</h2><small>{{data.occurrences.total}} total</small></div><label class="field">Selected occurrence<select :value="selected?.id" @change="choose(($event.target as HTMLSelectElement).value)"><option v-if="selected&&!data.occurrences.items.some(o=>o.id===selected!.id)" :value="selected.id">{{date(selected.occurred_at)}} · {{selected.origin}}</option><option v-for="o in data.occurrences.items" :key="o.id" :value="o.id">{{date(o.at)}} · {{o.origin}}{{o.release?' · '+o.release:''}}</option></select></label><details><summary>Browse occurrence history</summary><ul class="occurrence-history"><li v-for="o in data.occurrences.items" :key="o.id"><button class="text-link" :aria-current="selected?.id===o.id?'true':undefined" @click="choose(o.id)">{{date(o.at)}}</button><small>{{o.origin}} · {{o.mode==='historical_import'?'Historical import':o.mode}}{{o.release?' · '+o.release:''}}</small></li></ul><div class="pagination"><button class="button" :disabled="data.occurrences.page<=1" @click="page(data.occurrences.page-1)">Previous</button><button class="button" :disabled="data.occurrences.page>=data.occurrences.last_page" @click="page(data.occurrences.page+1)">Next</button></div></details></section></aside></div><p class="data-caption">Retained snapshot · the original Telescope entry may have been pruned. <a v-if="selected?.telescope_url" :href="selected.telescope_url" target="_blank" rel="noopener noreferrer" class="text-link">Open in Telescope</a><br>Data as of {{date(data.window.as_of)}} · {{zone()}}</p></template></template>
